"""Runnable reduced benchmark case for Task 013."""

from __future__ import annotations

import json
from pathlib import Path

import numpy as np

from .assembly import assemble_kinetic_blocks_from_coefficients, assemble_potential_blocks_from_coefficients
from .coefficients import map_fourin_integrals_to_coefficients
from .energy import summarize_energy_path
from .modes import TerpsichoreModeTable
from .options import TerpsichoreBoundaryOptions
from .radial import TerpsichoreRadialGrid
from .trig import build_trig_table
from .verification import build_report, compare_case_reports, compare_ladder_reports


def load_case(path: str | Path) -> dict:
    with Path(path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def build_profiles(
    intervals: int,
    centers: np.ndarray,
    *,
    signal_scale: float = 1.0,
    boundary_options: TerpsichoreBoundaryOptions | None = None,
) -> dict[str, np.ndarray]:
    x = np.linspace(0.2, 0.95, intervals)
    if boundary_options is None:
        boundary_options = TerpsichoreBoundaryOptions()
    return {
        "ftp": signal_scale * (1.05 + 0.14 * x + 0.03 * x**2),
        "fpp": signal_scale * (0.82 + 0.18 * x + 0.04 * x**2),
        "boundary_response": boundary_options.response_profile(np.asarray(centers, dtype=float)),
        "boundary_closure": boundary_options.closure_profile(np.asarray(centers, dtype=float)),
    }


def build_reduced_integrals(trig_table, intervals: int, signal_scale: float = 1.0) -> tuple[np.ndarray, np.ndarray]:
    """Create deterministic raw FOURIN-like integrals for an offline fixture."""

    lss = trig_table.lss + 1
    cna = np.zeros((7, lss, intervals))
    cnb = np.zeros((7, lss, intervals))
    for interval in range(intervals):
        cna[:, 0, interval] = 97.0 + interval
        cnb[:, 0, interval] = -83.0 - interval
    for idx in range(1, lss):
        m_value = float(trig_table.msx[idx - 1])
        n_value = float(trig_table.nsx[idx - 1])
        spectral_strength = signal_scale * (1.0 + 0.12 * abs(m_value) + 0.17 * abs(n_value))
        for interval in range(intervals):
            radial = 1.0 + 0.30 * interval
            cna[1, idx, interval] = spectral_strength * radial * (0.28 + 0.04 * m_value)
            cna[6, idx, interval] = spectral_strength * radial * (0.40 + 0.03 * abs(n_value))
            cnb[1, idx, interval] = spectral_strength * radial * (0.35 + 0.05 * abs(n_value))
            cnb[2, idx, interval] = spectral_strength * radial * (0.88 + 0.04 * abs(m_value - n_value))
            cnb[4, idx, interval] = spectral_strength * radial * (0.52 + 0.06 * abs(n_value))
            cnb[5, idx, interval] = spectral_strength * radial * (0.24 + 0.03 * abs(m_value))
            cnb[6, idx, interval] = spectral_strength * radial * (0.32 + 0.04 * abs(m_value + n_value))
    return cna, cnb


def run_case(case_path: str | Path) -> dict:
    case = load_case(case_path)
    mode_table = TerpsichoreModeTable.from_pairs(case["modes"])
    radial_grid = TerpsichoreRadialGrid.uniform(int(case["radial_intervals"]))
    trig_table = build_trig_table(
        mode_table,
        nj=int(case["nj"]),
        nk=int(case["nk"]),
        nper=int(case["nper"]),
    )
    boundary_options = TerpsichoreBoundaryOptions.from_case(case)
    profiles = build_profiles(
        radial_grid.n_intervals,
        radial_grid.centers,
        signal_scale=float(case.get("signal_scale", 1.0)),
        boundary_options=boundary_options,
    )
    cna, cnb = build_reduced_integrals(
        trig_table,
        radial_grid.n_intervals,
        float(case.get("signal_scale", 1.0)),
    )
    coeffs = map_fourin_integrals_to_coefficients(
        cna=cna,
        cnb=cnb,
        mode_table=mode_table,
        trig_table=trig_table,
        profiles=profiles,
        dtdp=float(case.get("dtdp", 1.0)),
        cospar=float(case.get("cospar", 1.0)),
        cospr2=float(case.get("cospr2", 1.0)),
    )
    potential = assemble_potential_blocks_from_coefficients(
        coeffs=coeffs,
        radial_grid=radial_grid,
        mode_table=mode_table,
    )
    kinetic = assemble_kinetic_blocks_from_coefficients(
        coeffs=coeffs,
        radial_grid=radial_grid,
        mode_table=mode_table,
    )
    energy = summarize_energy_path(potential, kinetic)
    return build_report(case, coeffs, potential, kinetic, energy)


__all__ = [
    "build_profiles",
    "build_reduced_integrals",
    "compare_case_reports",
    "compare_ladder_reports",
    "load_case",
    "run_case",
]
